document.addEventListener('DOMContentLoaded', () => {
    loadFacilities();
});

async function loadFacilities() {
    const grid = document.querySelector('#facilities-grid .grid');
    if (!grid) return;

    try {
        // Call the Backend API from UC02
        const response = await fetch('/api/facilities?page=0&size=20');
        const data = await response.json();
        
        // Clear the dummy HTML generated by Stitch
        grid.innerHTML = '';

        if (!data.content || data.content.length === 0) {
            grid.innerHTML = '<p class="text-on-surface-variant">No facilities found.</p>';
            return;
        }

        // Render each facility using the data from the API
        data.content.forEach(facility => {
            // Build pills for storage types
            let typesHtml = '';
            if (facility.unitTypes) {
                facility.unitTypes.forEach(type => {
                    typesHtml += `<span class="font-label-sm text-label-sm bg-surface-container px-2 py-0.5 rounded text-on-surface-variant">${type.sizeName}</span> `;
                });
            }

            const card = document.createElement('div');
            card.className = "bg-surface-container-lowest rounded-xl overflow-hidden shadow-sm hover:shadow-lg transition-all flex flex-col";
            card.innerHTML = `
              <div class="relative h-48 w-full overflow-hidden bg-surface-container-high flex items-center justify-center">
                  <span class="material-symbols-outlined text-outline text-[48px]">warehouse</span>
                  <div class="absolute top-3 left-3 flex gap-1.5">
                      <span class="inline-flex items-center gap-1 px-2.5 py-1 rounded-full font-label-sm text-label-sm bg-tertiary text-on-tertiary shadow-sm">
                          <span class="w-1.5 h-1.5 rounded-full bg-tertiary-fixed"></span>Available
                      </span>
                  </div>
                  <div class="absolute bottom-3 right-3 bg-inverse-surface/80 text-inverse-on-surface px-2.5 py-1 rounded-md text-label-sm font-label-sm backdrop-blur-sm">
                      ${facility.availableUnitsCount} Units Left
                  </div>
              </div>
              <div class="p-space-lg flex-1 flex flex-col justify-between gap-space-md">
                  <div class="flex flex-col gap-space-xs">
                      <h3 class="font-headline-md text-headline-md text-on-surface">${facility.name}</h3>
                      <p class="font-body-sm text-body-sm text-on-surface-variant flex items-start gap-1">
                          <span class="material-symbols-outlined text-[16px] text-secondary shrink-0 mt-0.5">pin_drop</span>
                          <span>${facility.address}</span>
                      </p>
                      <div class="mt-space-xs flex flex-wrap gap-1.5">
                          ${typesHtml}
                      </div>
                  </div>
                  <div class="pt-space-md border-t border-surface-container flex items-center justify-between">
                      <div>
                          <span class="font-label-sm text-label-sm text-on-surface-variant block">Starting price</span>
                          <span class="font-headline-sm text-headline-sm font-bold text-on-surface">
                              ${facility.startingPrice ? 'From ' + facility.startingPrice.toLocaleString('vi-VN') : 'N/A'}
                              <span class="text-label-sm font-normal text-on-surface-variant">VND/mo</span>
                          </span>
                      </div>
                      <button onclick="alert('Phần chi tiết kho và báo giá (UC04) chưa có giao diện HTML từ Frontend nên tạm thời chưa click được!');" class="inline-flex items-center gap-1 font-label-lg text-label-lg text-primary hover:text-secondary transition-colors font-medium">
                          <span>View Facility</span>
                          <span class="material-symbols-outlined text-[18px]">chevron_right</span>
                      </button>
                  </div>
              </div>
            `;
            grid.appendChild(card);
        });

    } catch (error) {
        console.error('Error fetching facilities:', error);
        grid.innerHTML = '<p class="text-error">Failed to load facilities data. Ensure the API is running.</p>';
    }
}
